const triggerData = $('Telegram Trigger').item.json;
const caption = triggerData.message.caption || 'Der Besucher hat dir ein Foto geschickt. Schau es dir an und reagiere darauf.';

// Ergebnis der Gesichtserkennung aus dem HTTP-Node holen
const face = $('HTTP Request').item.json;
const isMatch = face.match === true;

// Hinweis fuer den AI Agent zusammenbauen
let faceHint;
if (isMatch) {
  faceHint = 'HINWEIS: Auf diesem Foto wurde Aline erkannt.';
} else {
  faceHint = 'HINWEIS: Auf diesem Foto wurde Aline nicht erkannt.';
}

return {
  json: {
    chatInput: caption + '\n\n' + faceHint,
    faceMatch: isMatch
  },
  binary: $('Download Picture').item.binary
};

return {
  json: {
    resetMessage: '<i>Chat has been reset. Start again. </i>'
  }
};

const data = $('Telegram Trigger').item.json;
const chatId = data.message.chat.id;
const text = data.message.text;

const staticData = $getWorkflowStaticData('global');
const key = 'round_' + chatId;

// Wenn die Nachricht /neu ist: Runden-Nummer erhoehen
if (text === '/neu') {
  staticData[key] = (staticData[key] || 0) + 1;
}

// Aktuelle Runden-Nummer holen (Standard 0)
const round = staticData[key] || 0;

// Fertigen Session-Key bauen und die Original-Nachricht durchreichen
return {
  json: {
    ...data,
    sessionKey: chatId + '_' + round
  }
};

// Dions Antwort holen
const output = $('AI Agent').item.json.output || '';

// An Leerzeilen (doppelten Umbruechen) zerlegen
const parts = output
  .split(/\n\s*\n/)        // an einer oder mehr Leerzeilen trennen
  .map(p => p.trim())      // Leerraum an den Raendern entfernen
  .filter(p => p.length > 0); // leere Teile rauswerfen

// Falls nichts Sinnvolles rauskam, ganze Antwort als ein Teil senden
const messages = parts.length > 0 ? parts : [output.trim()];

// Fuer jeden Teil ein eigenes Item erzeugen
return messages.map(msg => ({
  json: { message: msg }
}));
